const rows = [fields.map(csv).join(',')];
for (const id of originalIds) {
  const fort = inventory.get(id);
  if (!fort) throw new Error(`Original catalogue id missing from forts.js: ${id}`);
  const refs = catalogue.filter((source) => source.fort === id);
  const plans = refs.filter((source) => ['site-plans','historic-maps'].includes(source.category));
  const images = refs.filter((source) => ['elevations-details','views'].includes(source.category));
  const level = levels.get(id);
  const sourceText = sourceById.get(id) ?? '';
  const sceneKind = !level ? 'no scene' : id === 'tughlaqabad' ? 'hand-traced plan blockout; georeferencing and fidelity unverified' : ['bidar','gulbarga','bijapur-arkilla','raichur','naldurg'].includes(id) ? 'multi-circuit plan-informed blockout; georeferencing and fidelity unverified' : /makeFort\s*\(/.test(sourceText) ? 'generated schematic; fidelity unverified' : 'hand-authored scene; fidelity unverified';
  const row = [id, fort.name, fort.country, fort.region, fort.lat, fort.lon,
    level ? 'yes' : 'no', sceneKind,
    refs.length, plans.length, images.length,
    ...(reviews[id] ?? ['UNREVIEWED','UNREVIEWED','UNREVIEWED','UNREVIEWED','UNREVIEWED','UNREVIEWED','UNREVIEWED','UNREVIEWED','NOT VERIFIED','queued','']),
    'Compare official survey/heritage documentation, historic plans and dated images with current terrain imagery; record conflicts and source locators.'];
  rows.push(row.map(csv).join(','));
}
await writeFile(output, `${rows.join('\n')}\n`);
console.log(`Wrote ${originalIds.length} audit rows to ${output}`);
